//! Canonical-convention boundary suite (`cargo test -p drm-spatial conventions`):
//! NED/`OpenCV`/Unity/Unreal boundary tables convert explicitly and match the
//! independent E4 `NumPy` oracle (`tests/oracle/conventions_oracle.py`); internal
//! values stay canonical (`I-S4`, [spatial-core.md] §Invariants `I-S4`).
//!
//! REQ: REQ-SPATIAL-007, REQ-SPATIAL-040.

use drm_spatial::{BoundaryConvention, Point3, Transform3};
use serde_json::Value;

/// The committed oracle fixture generated by `tests/oracle/conventions_oracle.py`.
/// REQ: REQ-SPATIAL-040.
fn oracle() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/fixtures/spatial/convention_vectors.json"
    );
    let text = std::fs::read_to_string(path).unwrap_or_else(|e| unreachable!("oracle: {e}"));
    serde_json::from_str(&text).unwrap_or_else(|e| unreachable!("parse oracle: {e}"))
}

/// Maps an oracle convention name to the enum value.
/// REQ: REQ-SPATIAL-040.
fn convention_of(name: &str) -> BoundaryConvention {
    match name {
        "ned" => BoundaryConvention::Ned,
        "opencv_optical" => BoundaryConvention::OpenCvOptical,
        "unity" => BoundaryConvention::Unity,
        "unreal" => BoundaryConvention::Unreal,
        other => unreachable!("unknown convention {other}"),
    }
}

/// Reads a 3-element `f64` array.
/// REQ: REQ-SPATIAL-040.
fn arr3(v: &Value) -> [f64; 3] {
    let a = v.as_array().unwrap_or_else(|| unreachable!("array"));
    [
        a[0].as_f64().unwrap_or_default(),
        a[1].as_f64().unwrap_or_default(),
        a[2].as_f64().unwrap_or_default(),
    ]
}

/// Reads a 4-element `f64` array.
/// REQ: REQ-SPATIAL-040.
fn arr4(v: &Value) -> [f64; 4] {
    let a = v.as_array().unwrap_or_else(|| unreachable!("array"));
    [
        a[0].as_f64().unwrap_or_default(),
        a[1].as_f64().unwrap_or_default(),
        a[2].as_f64().unwrap_or_default(),
        a[3].as_f64().unwrap_or_default(),
    ]
}

/// REQ: REQ-SPATIAL-007, REQ-SPATIAL-040 — `spatial_convention_boundary`: every
/// boundary conversion matches the oracle for points and rigid transforms.
#[test]
fn spatial_convention_boundary() {
    let doc = oracle();
    let cases = doc["cases"]
        .as_array()
        .unwrap_or_else(|| unreachable!("cases"));
    assert_eq!(cases.len(), 4);
    for case in cases {
        let conv = convention_of(case["convention"].as_str().unwrap_or_default());
        let points = case["points"]
            .as_array()
            .unwrap_or_else(|| unreachable!("points"));
        let expected = case["to_canonical"]
            .as_array()
            .unwrap_or_else(|| unreachable!("to_canonical"));
        for (p, want) in points.iter().zip(expected) {
            let got = conv.point_to_canonical(Point3 {
                x: p[0].as_f64().unwrap_or_default(),
                y: p[1].as_f64().unwrap_or_default(),
                z: p[2].as_f64().unwrap_or_default(),
            });
            let want = arr3(want);
            assert!(
                (got.x - want[0]).abs() < 1e-9,
                "point x {:?}",
                case["convention"]
            );
            assert!(
                (got.y - want[1]).abs() < 1e-9,
                "point y {:?}",
                case["convention"]
            );
            assert!(
                (got.z - want[2]).abs() < 1e-9,
                "point z {:?}",
                case["convention"]
            );
        }

        let t = Transform3::new(arr3(&case["transform_t"]), arr4(&case["transform_q"]))
            .unwrap_or_else(|e| unreachable!("{e}"));
        let canon = conv.transform_to_canonical(&t);
        let wt = arr3(&case["transform_to_canonical_t"]);
        assert!((canon.translation[0] - wt[0]).abs() < 1e-9);
        assert!((canon.translation[1] - wt[1]).abs() < 1e-9);
        assert!((canon.translation[2] - wt[2]).abs() < 1e-9);
        let wq = arr4(&case["transform_to_canonical_q"]);
        assert!(
            quat_close(canon.rotation, wq),
            "quat {:?}",
            case["convention"]
        );
    }
}

/// Quaternion equality up to sign (`q` and `-q` are the same rotation).
/// REQ: REQ-SPATIAL-040.
fn quat_close(got: [f64; 4], want: [f64; 4]) -> bool {
    let direct = (0..4).all(|i| (got[i] - want[i]).abs() < 1e-9);
    let negated = (0..4).all(|i| (got[i] + want[i]).abs() < 1e-9);
    direct || negated
}

/// REQ: REQ-SPATIAL-007 — the canonical convention is right-handed: `X × Y = Z`.
#[test]
#[allow(clippy::float_cmp)] // exact integer-valued axis components
fn canonical_is_right_handed() {
    let x = [1.0, 0.0, 0.0];
    let y = [0.0, 1.0, 0.0];
    let cross = [
        x[1] * y[2] - x[2] * y[1],
        x[2] * y[0] - x[0] * y[2],
        x[0] * y[1] - x[1] * y[0],
    ];
    assert_eq!(cross, [0.0, 0.0, 1.0]);
}
